    "tipoNombre": "Licitación Pública >1000 UTM",
    "titulo": "HABILITACION CENTRAL DE MONITOREO CHIGUAYANTE.",
    "organismo": "I MUNICIPALIDAD DE CHIGUAYANTE",
    "organismoRut": "69.264.700-9",
    "organismoPagoDias": null,
    "organismoRiesgo": "Sin evaluar",
